insert into public.sports (id, name, lower_body_load, upper_body_load, eccentric_impact, conditioning, muscles_stressed, default_minutes, notes) values ('football', 'Football (soccer)', 3, 0, 3, 3, array['quads','hamstrings','glutes','calves','adductors']::text[], 90, 'Sprints, cuts and kicks load the legs hard; keep heavy leg work at least 24 h before a match or hard session and not the day after a match.') on conflict (id) do update set name = excluded.name, lower_body_load = excluded.lower_body_load, upper_body_load = excluded.upper_body_load, eccentric_impact = excluded.eccentric_impact, conditioning = excluded.conditioning, muscles_stressed = excluded.muscles_stressed, default_minutes = excluded.default_minutes, notes = excluded.notes;
insert into public.sports (id, name, lower_body_load, upper_body_load, eccentric_impact, conditioning, muscles_stressed, default_minutes, notes) values ('running', 'Running', 2, 0, 2, 3, array['quads','calves','hamstrings']::text[], 45, 'Running interferes most with leg training; do easy runs after lifting or on other days and keep intervals away from leg day.') on conflict (id) do update set name = excluded.name, lower_body_load = excluded.lower_body_load, upper_body_load = excluded.upper_body_load, eccentric_impact = excluded.eccentric_impact, conditioning = excluded.conditioning, muscles_stressed = excluded.muscles_stressed, default_minutes = excluded.default_minutes, notes = excluded.notes;
insert into public.sports (id, name, lower_body_load, upper_body_load, eccentric_impact, conditioning, muscles_stressed, default_minutes, notes) values ('boxing', 'Boxing', 1, 2, 1, 3, array['front_delts','side_delts','triceps','calves']::text[], 60, 'Rounds tax shoulders, arms and footwork; avoid heavy pressing right before. Legs are mostly fine.') on conflict (id) do update set name = excluded.name, lower_body_load = excluded.lower_body_load, upper_body_load = excluded.upper_body_load, eccentric_impact = excluded.eccentric_impact, conditioning = excluded.conditioning, muscles_stressed = excluded.muscles_stressed, default_minutes = excluded.default_minutes, notes = excluded.notes;
insert into public.sports (id, name, lower_body_load, upper_body_load, eccentric_impact, conditioning, muscles_stressed, default_minutes, notes) values ('tennis', 'Tennis', 2, 2, 2, 2, array['quads','calves','side_delts','front_delts','forearms']::text[], 90, 'Lateral cuts and serves; treat it like a moderate leg and shoulder day.') on conflict (id) do update set name = excluded.name, lower_body_load = excluded.lower_body_load, upper_body_load = excluded.upper_body_load, eccentric_impact = excluded.eccentric_impact, conditioning = excluded.conditioning, muscles_stressed = excluded.muscles_stressed, default_minutes = excluded.default_minutes, notes = excluded.notes;
insert into public.sports (id, name, lower_body_load, upper_body_load, eccentric_impact, conditioning, muscles_stressed, default_minutes, notes) values ('swimming', 'Swimming', 1, 2, 0, 3, array['back','front_delts','side_delts','triceps']::text[], 45, 'Low impact and great conditioning; shoulders and lats get extra work.') on conflict (id) do update set name = excluded.name, lower_body_load = excluded.lower_body_load, upper_body_load = excluded.upper_body_load, eccentric_impact = excluded.eccentric_impact, conditioning = excluded.conditioning, muscles_stressed = excluded.muscles_stressed, default_minutes = excluded.default_minutes, notes = excluded.notes;
insert into public.sports (id, name, lower_body_load, upper_body_load, eccentric_impact, conditioning, muscles_stressed, default_minutes, notes) values ('cycling', 'Cycling', 2, 0, 0, 3, array['quads','glutes','calves']::text[], 60, 'Little eccentric load, so it is the most lifting-friendly cardio, but hard intervals still tire the quads.') on conflict (id) do update set name = excluded.name, lower_body_load = excluded.lower_body_load, upper_body_load = excluded.upper_body_load, eccentric_impact = excluded.eccentric_impact, conditioning = excluded.conditioning, muscles_stressed = excluded.muscles_stressed, default_minutes = excluded.default_minutes, notes = excluded.notes;
